import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.WFmvnizL.js";const m=JSON.parse('{"title":"What is Nezha Monitoring V2?","description":"Official Nezha Monitoring V2 overview explaining how Dashboard and Agent provide multi-server metrics, network service checks, alerts, and authorized operations, and which use cases fit the project.","frontmatter":{"title":"What is Nezha Monitoring V2?","description":"Official Nezha Monitoring V2 overview explaining how Dashboard and Agent provide multi-server metrics, network service checks, alerts, and authorized operations, and which use cases fit the project.","outline":"deep"},"headers":[],"relativePath":"en_US/guide/overview.md","filePath":"en_US/guide/overview.md","lastUpdated":1785844584000}'),n={name:"en_US/guide/overview.md"};function i(s,e,d,h,c,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-is-nezha-monitoring-v2" tabindex="-1">What is Nezha Monitoring V2? <a class="header-anchor" href="#what-is-nezha-monitoring-v2" aria-label="Permalink to &quot;What is Nezha Monitoring V2?&quot;">​</a></h1><p><strong>Nezha Monitoring V2 is an open-source, self-hosted server monitoring and operations tool.</strong> It combines a central Dashboard with an Agent installed on each monitored device. Together they provide a unified view of server status, website and network-service checks, alerts, and authorized operations such as terminal, file, and task access.</p><p>Nezha is designed for individuals and teams that want a straightforward web interface for VPS fleets, cloud servers, home labs, NAS devices, or geographically distributed nodes. It focuses on quick deployment and day-to-day infrastructure operations. It is not intended to replace a log analytics platform, application performance monitoring system, or general-purpose metrics query platform.</p><h2 id="core-components" tabindex="-1">Core components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Where it runs</th><th>Primary responsibility</th><th>Official source</th></tr></thead><tbody><tr><td>Dashboard</td><td>A server reachable by administrators and Agents</td><td>Receives Agent state, stores configuration, presents data, schedules checks and tasks, sends notifications, and exposes APIs and the admin UI</td><td><a href="https://github.com/nezhahq/nezha" target="_blank" rel="noreferrer">nezhahq/nezha</a></td></tr><tr><td>Agent</td><td>Every monitored server or device</td><td>Collects host state, reports to Dashboard, performs assigned service checks, and accepts authorized tasks according to its configuration</td><td><a href="https://github.com/nezhahq/agent" target="_blank" rel="noreferrer">nezhahq/agent</a></td></tr><tr><td>User and admin frontends</td><td>Served by Dashboard</td><td>Provide public or authenticated status views and management for servers, services, notifications, tasks, users, and settings</td><td>Released with Dashboard</td></tr></tbody></table><p>Dashboard and Agent have independent release versions. Check <a href="https://github.com/nezhahq/nezha/releases" target="_blank" rel="noreferrer">Dashboard Releases</a> and <a href="https://github.com/nezhahq/agent/releases" target="_blank" rel="noreferrer">Agent Releases</a> before upgrading either component. “V2” identifies the current product generation; it is not the complete version number of every component. See <a href="/en_US/guide/version-compatibility.html">Version and compatibility</a>.</p><h2 id="what-can-nezha-monitor" tabindex="-1">What can Nezha monitor? <a class="header-anchor" href="#what-can-nezha-monitor" aria-label="Permalink to &quot;What can Nezha monitor?&quot;">​</a></h2><h3 id="server-state" tabindex="-1">Server state <a class="header-anchor" href="#server-state" aria-label="Permalink to &quot;Server state&quot;">​</a></h3><p>The Agent reports online status and available metrics such as CPU, memory, swap, disk, network traffic, load, connection count, process count, and uptime. Some data depends on the operating system, permissions, and Agent configuration. GPU and temperature reporting also require supported hardware and explicit configuration.</p><h3 id="websites-and-network-services" tabindex="-1">Websites and network services <a class="header-anchor" href="#websites-and-network-services" aria-label="Permalink to &quot;Websites and network services&quot;">​</a></h3><p>Service monitoring supports HTTP GET, ICMP Ping, and TCPing. Checks can run from selected Agents to measure availability and latency, and HTTPS targets can be checked for certificate status. See <a href="/en_US/guide/services.html">Service monitoring</a> for fields and history behavior.</p><h3 id="alerts-and-notifications" tabindex="-1">Alerts and notifications <a class="header-anchor" href="#alerts-and-notifications" aria-label="Permalink to &quot;Alerts and notifications&quot;">​</a></h3><p>Administrators can notify on conditions such as offline state, resource usage, traffic, service failure, latency changes, and certificate status. Delivery methods, notification groups, and templates are configured in Dashboard. See <a href="/en_US/guide/notifications.html">Notifications</a>.</p><h3 id="authorized-operations" tabindex="-1">Authorized operations <a class="header-anchor" href="#authorized-operations" aria-label="Permalink to &quot;Authorized operations&quot;">​</a></h3><p>Nezha also provides web terminal, file management, scheduled and triggered tasks, DDNS, NAT, REST API, and MCP features. These features expand the Dashboard and Agent trust boundary. Enable only what you need and combine user roles, API Token scopes, Agent disable options, and network access controls.</p><h2 id="how-does-one-data-flow-work" tabindex="-1">How does one data flow work? <a class="header-anchor" href="#how-does-one-data-flow-work" aria-label="Permalink to &quot;How does one data flow work?&quot;">​</a></h2><ol><li>An Agent connects with credentials generated from the Dashboard server page.</li><li>The Agent continuously reports host information and runtime state.</li><li>Dashboard keeps current state in memory and stores business data according to its configuration. When TSDB is enabled, it can retain and query longer metric history.</li><li>Dashboard serves that state to the user frontend, admin frontend, and authorized API clients.</li><li>When a service check or task requires an Agent, Dashboard sends the request over the established connection and receives the result.</li><li>When an alert rule is satisfied, Dashboard invokes the configured notification method.</li></ol><p>See <a href="/en_US/guide/architecture.html">Architecture and data flow</a> for connections, storage, and reverse-proxy implications.</p><h2 id="which-use-cases-fit" tabindex="-1">Which use cases fit? <a class="header-anchor" href="#which-use-cases-fit" aria-label="Permalink to &quot;Which use cases fit?&quot;">​</a></h2><ul><li>View availability and resource usage for VPS, cloud, and home-lab servers in one interface.</li><li>Check websites, ports, network latency, and TLS certificates from different network locations.</li><li>Give a small operations team a self-hosted status, alerting, and common remote-operations entry point.</li><li>Connect server inventory, metric queries, and limited operations to internal automation through REST API or MCP.</li></ul><p>If your primary need is a public uptime page, second-by-second deep observability, the PromQL ecosystem, or large enterprise network management, read the <a href="/en_US/guide/comparison.html">monitoring tool comparison</a> before choosing Nezha, another tool, or a combined deployment.</p><h2 id="where-should-i-start" tabindex="-1">Where should I start? <a class="header-anchor" href="#where-should-i-start" aria-label="Permalink to &quot;Where should I start?&quot;">​</a></h2><ol><li>Read <a href="/en_US/guide/architecture.html">Architecture and data flow</a> to understand network and trust boundaries.</li><li><a href="/en_US/guide/dashboard.html">Install Dashboard</a> and replace the default password immediately.</li><li><a href="/en_US/guide/agent.html">Install Agent</a> and confirm the node is online.</li><li>Configure <a href="/en_US/guide/services.html">service monitoring</a> and <a href="/en_US/guide/notifications.html">notifications</a>.</li><li>Review the <a href="/en_US/guide/security.html">security and privacy checklist</a> before production use.</li></ol><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h2><h3 id="is-nezha-monitoring-free-and-open-source" tabindex="-1">Is Nezha Monitoring free and open source? <a class="header-anchor" href="#is-nezha-monitoring-free-and-open-source" aria-label="Permalink to &quot;Is Nezha Monitoring free and open source?&quot;">​</a></h3><p>The Dashboard and Agent source code is published in the NezhaHQ GitHub repositories. A deployment still has server, domain, storage, and notification-service costs and remains subject to repository licenses and third-party service terms.</p><h3 id="does-nezha-monitoring-require-a-cloud-service" tabindex="-1">Does Nezha Monitoring require a cloud service? <a class="header-anchor" href="#does-nezha-monitoring-require-a-cloud-service" aria-label="Permalink to &quot;Does Nezha Monitoring require a cloud service?&quot;">​</a></h3><p>No. Dashboard and Agent can be self-hosted. Agents must still be able to reach Dashboard. OAuth2, external notifications, CDNs, and DNS providers are contacted only when you choose those integrations.</p><h3 id="can-one-dashboard-monitor-multiple-servers" tabindex="-1">Can one Dashboard monitor multiple servers? <a class="header-anchor" href="#can-one-dashboard-monitor-multiple-servers" aria-label="Permalink to &quot;Can one Dashboard monitor multiple servers?&quot;">​</a></h3><p>Yes. Install an Agent on each server and connect them to the same Dashboard, then organize access with groups, users, and service coverage rules.</p><h3 id="does-api-v1-mean-that-i-am-using-nezha-v1" tabindex="-1">Does <code>/api/v1</code> mean that I am using Nezha V1? <a class="header-anchor" href="#does-api-v1-mean-that-i-am-using-nezha-v1" aria-label="Permalink to &quot;Does `/api/v1` mean that I am using Nezha V1?&quot;">​</a></h3><p>No. <code>/api/v1</code> names an API route version. The current product generation is V2. Product generation, Dashboard release, Agent release, and API path version are separate concepts.</p><h3 id="does-nezha-automatically-make-my-servers-secure" tabindex="-1">Does Nezha automatically make my servers secure? <a class="header-anchor" href="#does-nezha-automatically-make-my-servers-secure" aria-label="Permalink to &quot;Does Nezha automatically make my servers secure?&quot;">​</a></h3><p>No. Nezha provides authentication, permission, and security configuration controls, but the operator remains responsible for TLS, reverse proxy settings, secrets, users, firewall rules, backups, and updates. Follow the <a href="/en_US/guide/security.html">security and privacy guide</a>.</p>',34)])])}const p=a(n,[["render",i]]);export{m as __pageData,p as default};
